import{Ft as ZC,It as Zh,Tn as iu,Ut as _v,an as cu,c as Bi,tn as cI}from"./chunk-Cipn9wEx.js";import"./chunk-CGylB2X8.js";import"./main-M7WUAUGZ.js";import{t as G}from"./chunk-l5Zebelv.js";import{t as v}from"./chunk-D9xRcJuC.js";var u=class s{info=G;static ɵfac=function(r){return new(r||s)};static ɵcmp=cI({type:s,selectors:[[`app-privacy-policy`]],decls:198,vars:6,consts:[[`title`,`Privacy Policy`,`summary`,`A free personal project. I do not charge you or take your payment details. The public guides carry Google advertising; the signed-in app does not.`],[1,`space-y-8`,`text-sm`,`leading-relaxed`,`text-slate-700`],[1,`text-lg`,`font-bold`,`text-slate-900`],[1,`mt-3`,`list-disc`,`space-y-2`,`pl-5`],[1,`mt-3`],[1,`mt-4`,`font-semibold`,`text-slate-900`],[1,`mt-2`],[`href`,`/cookies.html`],[`href`,`https://www.google.com/settings/ads`,`rel`,`noopener`,`target`,`_blank`,1,`font-semibold`,`text-blue-600`,`hover:text-blue-500`,`dark:text-blue-400`,`dark:hover:text-blue-300`],[`href`,`https://www.aboutads.info/choices/`,`rel`,`noopener`,`target`,`_blank`,1,`font-semibold`,`text-blue-600`,`hover:text-blue-500`,`dark:text-blue-400`,`dark:hover:text-blue-300`],[`href`,`https://www.youronlinechoices.eu/`,`rel`,`noopener`,`target`,`_blank`,1,`font-semibold`,`text-blue-600`,`hover:text-blue-500`,`dark:text-blue-400`,`dark:hover:text-blue-300`],[`href`,`https://policies.google.com/privacy`,`rel`,`noopener`,`target`,`_blank`,1,`font-semibold`,`text-blue-600`,`hover:text-blue-500`,`dark:text-blue-400`,`dark:hover:text-blue-300`],[`href`,`https://www.google.com/policies/technologies/partner-sites/`,`rel`,`noopener`,`target`,`_blank`,1,`font-semibold`,`text-blue-600`,`hover:text-blue-500`,`dark:text-blue-400`,`dark:hover:text-blue-300`],[`href`,`/cookies.html#cookie-controls`],[`href`,`/privacy.html`]],template:function(r,n){r&1&&(Bi(0,`app-legal-page`,0)(1,`div`,1)(2,`section`)(3,`h2`,2),ZC(4,`1. The short version`),iu(),Bi(5,`ul`,3)(6,`li`),ZC(7),iu(),Bi(8,`li`),ZC(9,` I do not sell your personal information, and I do not use your business records for advertising or profiling. `),iu(),Bi(10,`li`),ZC(11,` The public guide pages on this site show advertising from Google AdSense. The signed-in app does not, and the policy pages do not. `),iu(),Bi(12,`li`),ZC(13,` I do not take your data for myself. What exists is what you enter, kept in your own account so the app can work for you. `),iu(),Bi(14,`li`),ZC(15,` You can export or delete your data at any time, and you can change your advertising-cookie choices. `),iu()()(),Bi(16,`section`)(17,`h2`,2),ZC(18,`2. Who runs this app`),iu(),Bi(19,`p`,4),ZC(20),iu(),Bi(21,`p`,4),ZC(22),iu()(),Bi(23,`section`)(24,`h2`,2),ZC(25,` 3. What is stored to run the app `),iu(),Bi(26,`p`,4),ZC(27,` The app cannot work without some information. This is the complete list, and it exists only to provide the service to you: `),iu(),Bi(28,`h3`,5),ZC(29,` 3.1 Account information `),iu(),Bi(30,`p`,6),ZC(31,` When you create an account or sign in with Google, I receive your email address, your display name and a unique account identifier. Authentication is handled by Google Firebase Authentication. I never receive or store your Google password. `),iu(),Bi(32,`h3`,5),ZC(33,` 3.2 Business records you enter `),iu(),Bi(34,`p`,6),ZC(35,` The information you record in the app — milkman details, daily milk entries, milk rates, payments and your application settings — is stored in your account so it is available on every device you sign in from. It is your data, not mine. `),iu(),Bi(36,`h3`,5),ZC(37,` 3.3 Security and device information `),iu(),Bi(38,`p`,6),ZC(39,` To help you review account activity, the app records sign-in sessions and trusted devices, including a timestamp, the browser's user agent string, and the IP address and approximate geographic location reported for that connection. The approximate location is obtained by sending the request's IP address to the third-party service ipwho.is (see section 6). `),iu(),Bi(40,`h3`,5),ZC(41,`3.4 Preferences`),iu(),Bi(42,`p`,6),ZC(43,` Formatting choices such as your currency and colour theme are stored with your settings so the app displays consistently on every device. `),iu(),Bi(44,`h3`,5),ZC(45,`3.5 Contact form`),iu(),Bi(46,`p`,6),ZC(47,` The name, email address, optional phone number and message you enter on the contact page are used only to reply to you. They are not added to a mailing list and are not used for marketing. `),iu(),Bi(48,`p`,6),ZC(49,` The form is delivered to my inbox by Web3Forms and protected by an hCaptcha check (see section 6). I keep nothing beyond the reply I send you. `),iu()(),Bi(50,`section`)(51,`h2`,2),ZC(52,` 4. Cookies and local storage `),iu(),Bi(53,`p`,4),ZC(54,` The app keeps a small amount of data in your browser's storage so it can work: the restored sign-in session, your theme and preference choices, and the files and queued offline entries the Progressive Web App needs. This storage is functional and is not used for advertising. `),iu(),Bi(55,`p`,4),ZC(56,` The public guide pages additionally load Google advertising, which may set cookies. The full list, with controls, is in the `),Bi(57,`a`,7),ZC(58,`cookie policy`),iu(),ZC(59,`. `),iu()(),Bi(60,`section`)(61,`h2`,2),ZC(62,` 5. Advertising on the public guides `),iu(),Bi(63,`p`,4),ZC(64,` Advertising is served by Google AdSense only on the individual guide articles that contain substantial editorial content. It is not used on the signed-in app, the guides index, the about page, the contact page or any policy page. Advertising is labelled and kept separate from editorial content. `),iu(),Bi(65,`p`,4),ZC(66,` Google uses cookies to help serve the ads it displays on this site. When you visit a page that carries advertising, a cookie may be placed on your browser. The required disclosures are: `),iu(),Bi(67,`ul`,3)(68,`li`),ZC(69,` Third party vendors, including Google, use cookies to serve ads based on a user's prior visits to this website or other websites. `),iu(),Bi(70,`li`),ZC(71,` Google's use of advertising cookies enables it and its partners to serve ads to users based on their visit to this site and/or other sites on the Internet. `),iu(),Bi(72,`li`),ZC(73,` Users may opt out of personalized advertising by visiting `),Bi(74,`a`,8),ZC(75,` Google Ads Settings `),iu(),ZC(76,`. Alternatively, users can opt out of a third-party vendor's use of cookies for personalised advertising by visiting `),Bi(77,`a`,9),ZC(78,` www.aboutads.info `),iu(),ZC(79,`. `),iu()(),Bi(80,`p`,4),ZC(81,` Further opt-outs are available at `),Bi(82,`a`,10),ZC(83,` youronlinechoices.eu `),iu(),ZC(84,`. The vendor serving advertising is Google; its privacy policy is at `),Bi(85,`a`,11),ZC(86,` policies.google.com/privacy `),iu(),ZC(87,`. Vendors may place and read cookies, web beacons, IP addresses and other identifiers as a result of ad serving. `),iu(),Bi(88,`p`,4),ZC(89,` How Google uses information from sites and apps that use its services: `),Bi(90,`a`,12),ZC(91,` google.com/policies/technologies/partner-sites `),iu(),ZC(92,`. `),iu(),Bi(93,`p`,4),ZC(94,` Where the law requires consent — in the EEA, the UK, Switzerland and Brazil — Google's certified consent message records your choice before advertising cookies are set. This supports the GDPR, UK GDPR, LGPD and Google's EU user consent policy. You can change it from the `),Bi(95,`a`,13),ZC(96,`cookie controls`),iu(),ZC(97,`. `),iu(),Bi(98,`ul`,3)(99,`li`),ZC(100,` This site does not set cookies on Google's domains, and does not modify, intercept or delete cookies set on Google's domains. `),iu(),Bi(101,`li`),ZC(102,` It does not pass personally identifiable information to Google for advertising. `),iu(),Bi(103,`li`),ZC(104,` It does not collect precise device or GPS location for advertising. `),iu(),Bi(105,`li`),ZC(106,` It does not offer compensation for viewing or clicking ads, and does not ask visitors to click ads. `),iu(),Bi(107,`li`),ZC(108,` It does not use interest-based advertising to target children, and the site is not directed to children. `),iu(),Bi(109,`li`),ZC(110,` It does not sell personal information for money. Some advertising cookies may be treated as "sharing" or "targeted advertising" under certain US state privacy laws; the opt-out links above and the consent message let you limit that use. `),iu()()(),Bi(111,`section`)(112,`h2`,2),ZC(113,` 6. Service providers `),iu(),Bi(114,`p`,4),ZC(115,` The app and site rely on the following third parties. Each processes data only as needed to provide its service, and none of them receives payment from you: `),iu(),Bi(116,`ul`,3)(117,`li`)(118,`strong`),ZC(119,`Google Firebase`),iu(),ZC(120,` (Authentication, Cloud Firestore and Cloud Storage) — hosts your account and your business records. `),iu(),Bi(121,`li`)(122,`strong`),ZC(123,`Google AdSense`),iu(),ZC(124,` — serves advertising on the public guide pages and may set advertising cookies as described in section 5. `),iu(),Bi(125,`li`)(126,`strong`),ZC(127,`ipwho.is`),iu(),ZC(128,` — receives the IP address of a sign-in request in order to return an approximate city, region and country for your security activity list. `),iu(),Bi(129,`li`)(130,`strong`),ZC(131,`Web3Forms`),iu(),ZC(132,` — receives the contact form fields and forwards them to my email inbox. `),iu(),Bi(133,`li`)(134,`strong`),ZC(135,`hCaptcha`),iu(),ZC(136,` — checks the contact form for automated submissions. It is used only on the contact page. `),iu()(),Bi(137,`p`,4),ZC(138,` Data is transmitted over HTTPS. Firebase encrypts data in transit and at rest according to Google's own security documentation. `),iu()(),Bi(139,`section`)(140,`h2`,2),ZC(141,` 7. How information is used `),iu(),Bi(142,`ul`,3)(143,`li`),ZC(144,`To operate the app and display your records and reports.`),iu(),Bi(145,`li`),ZC(146,`To authenticate you and keep your account secure.`),iu(),Bi(147,`li`),ZC(148,` To show you recent account and security activity so unusual sign-ins are visible. `),iu(),Bi(149,`li`),ZC(150,`To export your database as JSON, and to import it on request.`),iu(),Bi(151,`li`),ZC(152,`To respond to your support requests and corrections.`),iu(),Bi(153,`li`),ZC(154,` To serve and measure advertising on the public guides, subject to your consent where required. `),iu()()(),Bi(155,`section`)(156,`h2`,2),ZC(157,` 8. Legal bases (EEA and UK) `),iu(),Bi(158,`ul`,3)(159,`li`)(160,`strong`),ZC(161,`Contract`),iu(),ZC(162,` — storing your account and records so the app can work for you. `),iu(),Bi(163,`li`)(164,`strong`),ZC(165,`Legitimate interests`),iu(),ZC(166,` — security, abuse prevention and answering support requests. `),iu(),Bi(167,`li`)(168,`strong`),ZC(169,`Consent`),iu(),ZC(170,` — advertising cookies where consent is required. You can withdraw it at any time. `),iu()()(),Bi(171,`section`)(172,`h2`,2),ZC(173,` 9. Your data, export and deletion `),iu(),Bi(174,`p`,4),ZC(175,` Your records belong to you. You can export your full database to CSV, PDF or JSON at any time, and import a JSON export on another device from the Data Management settings. `),iu(),Bi(176,`p`,4),ZC(177),iu(),Bi(178,`p`,4),ZC(179,` You can request access to, correction of, or deletion of your account data by writing from the address on the account. You can also object to processing based on legitimate interests, or complain to a data protection authority in your country. `),iu()(),Bi(180,`section`)(181,`h2`,2),ZC(182,` 10. International transfers `),iu(),Bi(183,`p`,4),ZC(184,` The service providers above are global providers and may process data outside your country. Where required, transfers rely on the safeguards those providers have published, such as standard contractual clauses. `),iu()(),Bi(185,`section`)(186,`h2`,2),ZC(187,`11. Children`),iu(),Bi(188,`p`,4),ZC(189),iu()(),Bi(190,`section`)(191,`h2`,2),ZC(192,` 12. Changes to this policy `),iu(),Bi(193,`p`,4),ZC(194,` I may update this policy as the app or the site changes. Material changes will be reflected in the "Last updated" date above. The static page at `),Bi(195,`a`,14),ZC(196,`/privacy.html`),iu(),ZC(197,` is the authoritative version if the two ever differ. `),iu()()()()),r&2&&(_v(7),cu(` `,n.info.appName,` is a free personal project. I do not charge you and I do not take payment details from you. `),_v(13),Zh(` `,n.info.appName,` is an independent personal project run by `,n.info.operatorName,`, an individual developer. It is not a company, there is no business entity behind it, and there is no team receiving your information. `),_v(2),cu(` You use `,n.info.appName,` with your own account. The business records you enter are yours. This policy explains where they are stored, when they leave your device, and what advertising on the public guides does. `),_v(155),cu(` Deleting your account removes your records from `,n.info.appName,`. Copies of exported files that you saved to your own device remain under your control and must be deleted by you. `),_v(12),cu(` `,n.info.appName,` is a business tool and is not directed to children. I do not knowingly collect information from children. `))},dependencies:[v],encapsulation:2})};export{u as PrivacyPolicyComponent};